-- Northwind sample data for the MySQL "Live Server" sandbox mode.
-- Import with:  mysql -h <host> -P <port> -u <user> -p <database> < northwind_mysql_import.sql
-- Matches the schema/data in public/northwind.sqlite, generated by
-- scripts/generate_northwind.py, so sandbox challenge reference queries
-- return the same results against either backend.


DROP TABLE IF EXISTS `Order Details`;
DROP TABLE IF EXISTS Orders;
DROP TABLE IF EXISTS Products;
DROP TABLE IF EXISTS Shippers;
DROP TABLE IF EXISTS Employees;
DROP TABLE IF EXISTS Customers;
DROP TABLE IF EXISTS Suppliers;
DROP TABLE IF EXISTS Categories;

CREATE TABLE Categories (
    CategoryID   INT PRIMARY KEY,
    CategoryName VARCHAR(50) NOT NULL,
    Description  VARCHAR(255)
);

CREATE TABLE Suppliers (
    SupplierID   INT PRIMARY KEY,
    CompanyName  VARCHAR(100) NOT NULL,
    City         VARCHAR(50),
    Country      VARCHAR(50)
);

CREATE TABLE Customers (
    CustomerID   VARCHAR(5) PRIMARY KEY,
    CompanyName  VARCHAR(100) NOT NULL,
    ContactName  VARCHAR(50),
    City         VARCHAR(50),
    Country      VARCHAR(50)
);

CREATE TABLE Employees (
    EmployeeID INT PRIMARY KEY,
    FirstName  VARCHAR(50) NOT NULL,
    LastName   VARCHAR(50) NOT NULL,
    Title      VARCHAR(50),
    HireDate   DATE,
    City       VARCHAR(50)
);

CREATE TABLE Shippers (
    ShipperID   INT PRIMARY KEY,
    CompanyName VARCHAR(50) NOT NULL,
    Phone       VARCHAR(20)
);

CREATE TABLE Products (
    ProductID     INT PRIMARY KEY,
    ProductName   VARCHAR(100) NOT NULL,
    SupplierID    INT,
    CategoryID    INT,
    UnitPrice     DECIMAL(10,2) NOT NULL,
    UnitsInStock  INT NOT NULL,
    Discontinued  TINYINT(1) NOT NULL DEFAULT 0,
    FOREIGN KEY (SupplierID) REFERENCES Suppliers(SupplierID),
    FOREIGN KEY (CategoryID) REFERENCES Categories(CategoryID)
);

CREATE TABLE Orders (
    OrderID     INT PRIMARY KEY,
    CustomerID  VARCHAR(5),
    EmployeeID  INT,
    OrderDate   DATE NOT NULL,
    ShipCountry VARCHAR(50),
    FOREIGN KEY (CustomerID) REFERENCES Customers(CustomerID),
    FOREIGN KEY (EmployeeID) REFERENCES Employees(EmployeeID)
);

CREATE TABLE `Order Details` (
    OrderDetailID INT PRIMARY KEY,
    OrderID       INT,
    ProductID     INT,
    UnitPrice     DECIMAL(10,2) NOT NULL,
    Quantity      INT NOT NULL,
    Discount      DECIMAL(4,2) NOT NULL DEFAULT 0,
    FOREIGN KEY (OrderID) REFERENCES Orders(OrderID),
    FOREIGN KEY (ProductID) REFERENCES Products(ProductID)
);








